p=Path('programs/task-29a6e5b5.py'); p.parent.mkdir(parents=True,exist_ok=True)
p.write_text('''def transform(grid):
    h,w=len(grid),len(grid[0])
    colors={v for row in grid for v in row if v}
    boxes={}
    for c in colors:
        pts=[(r,x) for r in range(h) for x in range(w) if grid[r][x]==c]
        boxes[c]=(min(r for r,x in pts),min(x for r,x in pts),max(r for r,x in pts),max(x for r,x in pts))
    top=min(b[0] for b in boxes.values())
    out=[[0]*w for _ in range(h)]
    for c,(r0,x0,r1,x1) in boxes.items():
        dr=top-r0
        for r in range(r0,r1+1):
            for x in range(x0,x1+1):
                if grid[r][x]==c and 0<=r+dr<h: out[r+dr][x]=c
    return out
''')
